static char g_desSwap[256];
static char g_desBuf[256];
static unsigned int g_desLen;
/* The two 64-bit DES keys of bnBootDes, generated by bnGetKey as four
   32-bit words. */
static unsigned long long g_keyWord[2];
/* CBC chaining value of bnBootDes. */
static unsigned long long g_bootKey64;

