/* clang-format on */

/* One DES permutation: bit `tab[i]` of the input (counted from 1 at the
   MSB) becomes bit i of the output; `bit` is the mask that walks the output. */
#define DES_PERMUTE(out, in, tab, n, i, bit)					\
	(out) = 0;								\
	(bit) = 0x8000000000000000ULL;						\
	for ((i) = 0; (i) < (n); ) {						\
		if ((in) & (0x8000000000000000ULL >> ((tab)[(i)++] - 1)))	\
			(out) |= (bit);						\
		(bit) >>= 1;							\
	}

/* Rotates a 28-bit key half (C or D) left by 1 or 2 bits. */
static inline unsigned long long des_rotl28(unsigned long long x, int n)
{
	if (n == 1)
		return (((x >> 27) & 1) | (x << 1)) & 0x0fffffff;
	else
		return (((x >> 26) & 3) | (x << 2)) & 0x0fffffff;
}

/* DES encryption of one 64-bit block, written bit by bit as in the
   standard. The L/R halves are kept in the high 32 bits of each word. */
static void desEncrypt(unsigned long long data, void *out, unsigned long long key)
{
	unsigned long long C[17], D[17], K[17], L[17], R[17];
	unsigned long long pc1, x, y;
	unsigned long long bit;
	int i, j, v;

	DES_PERMUTE(pc1, key, des_pc1, 56, i, bit);
	C[0] = pc1 >> 36;
	D[0] = (pc1 >> 8) & 0x0fffffff;

	for (i = 0; i < 16; i++) {
		C[i + 1] = des_rotl28(C[i], des_shifts[i]);
		D[i + 1] = des_rotl28(D[i], des_shifts[i]);
	}

	for (i = 1; i <= 16; i++) {
		x = (C[i] << 36) | (D[i] << 8);
		DES_PERMUTE(y, x, des_pc2, 48, j, bit);
		K[i] = y;
	}

	DES_PERMUTE(x, data, des_ip, 64, i, bit);
	L[0] = x & 0xffffffff00000000ULL;
	R[0] = x << 32;

	for (i = 1; i <= 16; i++) {
		L[i] = x = R[i - 1];
		DES_PERMUTE(y, x, des_e, 48, j, bit);
		y ^= K[i];
		y >>= 16;
		x = 0;
		for (j = 0; j < 8; j++) {
			v = y & 0x3f;
			x |= (unsigned long long)des_s[7 - j][(v & 0x20) | ((v >> 1) & 0x0f) | ((v << 4) & 0x10)]
			    << (32 + 4 * j);
			y >>= 6;
		}
		DES_PERMUTE(y, x, des_p, 32, j, bit);
		R[i] = L[i - 1] ^ y;
	}

	x = R[16] | (L[16] >> 32);
	DES_PERMUTE(y, x, des_fp, 64, i, bit);
	*(unsigned long long *)out = y;
}

/* DES decryption of one 64-bit block: the round keys are computed in one
   loop and applied in reverse order. */
static void desDecrypt(unsigned long long data, void *out, unsigned long long key)
{
	unsigned long long K[16], L[17], R[17];
	unsigned long long x, y, c, d, r, bit;
	int i, j, v;

	y = 0;
	bit = 0x8000000000000000ULL;
	for (i = 0; i < 56; i++) {
		if (key & (0x8000000000000000ULL >> (des_pc1[i] - 1)))
			y |= bit;
		bit >>= 1;
	}
	c = y >> 36;
	d = (y >> 8) & 0x0fffffff;

	for (i = 0; i < 16; i++) {
		c = des_rotl28(c, des_shifts[i]);
		d = des_rotl28(d, des_shifts[i]);
		x = (c << 36) | (d << 8);
		y = 0;
		bit = 0x8000000000000000ULL;
		for (j = 0; j < 48; j++) {
			if (x & (0x8000000000000000ULL >> (des_pc2[j] - 1)))
				y |= bit;
			bit >>= 1;
		}
		K[i] = y;
	}

	x = 0;
	bit = 0x8000000000000000ULL;
	for (i = 0; i < 64; i++) {
		if (data & (0x8000000000000000ULL >> (des_ip[i] - 1)))
			x |= bit;
		bit >>= 1;
	}
	L[0] = x & 0xffffffff00000000ULL;
	R[0] = x << 32;

	for (i = 1; i <= 16; i++) {
		L[i] = r = R[i - 1];
		y = 0;
		bit = 0x8000000000000000ULL;
		for (j = 0; j < 48; j++) {
			if (r & (0x8000000000000000ULL >> (des_e[j] - 1)))
				y |= bit;
			bit >>= 1;
		}
		y ^= K[16 - i];
		y >>= 16;
		x = 0;
		for (j = 0; j < 8; j++) {
			v = y & 0x3f;
			x |= (unsigned long long)des_s[7 - j][(v & 0x20) | ((v >> 1) & 0x0f) | ((v << 4) & 0x10)]
			    << (32 + 4 * j);
			y >>= 6;
		}
		y = 0;
		bit = 0x8000000000000000ULL;
		for (j = 0; j < 32; j++) {
			if (x & (0x8000000000000000ULL >> (des_p[j] - 1)))
				y |= bit;
			bit >>= 1;
		}
		R[i] = L[i - 1] ^ y;
	}

	x = R[16] | (L[16] >> 32);
	y = 0;
	bit = 0x8000000000000000ULL;
	for (i = 0; i < 64; i++) {
		if (x & (0x8000000000000000ULL >> (des_fp[i] - 1)))
			y |= bit;
		bit >>= 1;
	}
	*(unsigned long long *)out = y;
}

/* Seeds the PRNG with the time, generates four random key words, and
   copies them byte-swapped (16 bytes) to `out`. */
void bnGetKey(void *out)
{
	unsigned char *base;
	unsigned char *dst;
	unsigned char *src;
	int i;

	srand(time(0));

	((unsigned int *)g_keyWord)[0] = 0xd284c16d;  /* redundant as written */
	((unsigned int *)g_keyWord)[1] = 0xde41dff2;  /* redundant as written */
	((unsigned int *)g_keyWord)[2] = 0x11602ac2;  /* redundant as written */
	((unsigned int *)g_keyWord)[3] = 0xb852a4bf;  /* redundant as written */

	((unsigned int *)g_keyWord)[0] = rand() ^ 0x80123123;
	((unsigned int *)g_keyWord)[1] = rand() ^ 0xb1c9c021;
	((unsigned int *)g_keyWord)[2] = rand() ^ 0x134dcb0a;
	((unsigned int *)g_keyWord)[3] = rand() ^ 0x82551869;

	base = g_keyBytes;
	dst = base;
	src = (unsigned char *)g_keyWord;
	for (i = 3; i >= 0; i--) {
		dst[0] = src[3];
		dst[1] = src[2];
		dst[2] = src[1];
		dst[3] = src[0];
		src += 4;
		dst += 4;
	}

	memmove(out, base, 16);
}

/* Resets the CBC chaining value used by bnBootDes. */
void bnBootInit(void)
{
	g_bootKey64 = 0x0db583a35432cebdULL;
}

/* Encrypts the string `in` with 3DES-CBC (encrypt, decrypt, encrypt with
   the two halves of g_keyWord); the chaining value carries over between
   calls. The length is padded to the next multiple of 8 (a whole extra block
   when already aligned), and the result is copied to `out` with each 32-bit
   word byte-swapped. Returns the padded length. */
int bnBootDes(const char *in, char *out)
{
	unsigned long long blk;
	unsigned int n;
	char *buf;
	int i;

	buf = g_desBuf;
	n = (strlen(in) + 8) & ~7;
	g_desLen = n;
	memset(buf, 0, n + 1);
	strcpy(buf, in);

	for (i = 0; i < (int)(g_desLen >> 3); i++) {
		desEncrypt(((unsigned long long *)buf)[i] ^ g_bootKey64, &blk, g_keyWord[0]);
		desDecrypt(blk, &blk, g_keyWord[1]);
		desEncrypt(blk, &blk, g_keyWord[0]);
		((unsigned long long *)buf)[i] = blk;
		g_bootKey64 = blk;
	}

	memset(out, 0, g_desLen + 1);

	for (i = 0; i < g_desLen >> 2; i++) {
		g_desSwap[i * 4 + 0] = buf[i * 4 + 3];
		g_desSwap[i * 4 + 1] = buf[i * 4 + 2];
		g_desSwap[i * 4 + 2] = buf[i * 4 + 1];
		g_desSwap[i * 4 + 3] = buf[i * 4 + 0];
	}

	memmove(out, g_desSwap, g_desLen);
	return g_desLen;
}
